export type DronePartId =
  | 'airframe'
  | 'rotor'
  | 'electronics'
  | 'flight-controller'
  | 'sensor'
  | 'payload'
  | 'navigation';

export type DroneStage = 'dormant' | 'awaken' | 'unfold' | 'deploy' | 'activate';

export type DeploymentProgress = { value: number };

export type DronePart = {
  id: DronePartId;
  label: string;
  detail: string;
};

export const DRONE_PARTS: readonly DronePart[] = [
  { id: 'airframe', label: 'Airframe', detail: 'Mechanical design and rapid prototyping.' },
  { id: 'rotor', label: 'Rotor Assembly', detail: 'Flight control and autonomous navigation.' },
  { id: 'electronics', label: 'Embedded Electronics', detail: 'PCB design and embedded systems development.' },
  { id: 'flight-controller', label: 'Flight Controller', detail: 'Control systems and autonomous navigation.' },
  { id: 'sensor', label: 'Sensor Integration', detail: 'Sensor integration and control systems.' },
  { id: 'payload', label: 'Payload Management', detail: 'Mission planning and payload management.' },
  { id: 'navigation', label: 'Autonomous Navigation', detail: 'AI, computer vision, and autonomous flight.' },
];

export const getDroneStage = (progress: number): DroneStage => {
  if (progress < 0.15) return 'dormant';
  if (progress < 0.3) return 'awaken';
  if (progress < 0.6) return 'unfold';
  if (progress < 0.8) return 'deploy';
  return 'activate';
};

export const isOperationalStage = (stage: DroneStage) => stage === 'deploy' || stage === 'activate';
