'use client';

import { DRONE_PARTS, type DronePartId } from './types';

export function DroneAnnotations({ activePart, onSelect }: {
  activePart: DronePartId | null;
  onSelect: (part: DronePartId) => void;
}) {
  return (
    <ul className="system-callouts drone-annotations" aria-label="Autonomous drone system components">
      {DRONE_PARTS.map((part) => (
        <li key={part.id}>
          <button
            type="button"
            className={`system-callout ${activePart === part.id ? 'is-active' : ''}`}
            aria-pressed={activePart === part.id}
            onClick={() => onSelect(part.id)}
          >
            <span className="system-callout__mark" aria-hidden="true" />
            <span>
              <span className="system-callout__label">{part.label}</span>
              <span className="system-callout__detail">{part.detail}</span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
