'use client';

import dynamic from 'next/dynamic';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { DroneAnnotations } from './DroneAnnotations';
import { DroneSvgFallback } from './DroneSvgFallback';
import { getDroneStage, isOperationalStage, type DeploymentProgress, type DronePartId, type DroneStage } from './types';
import { useDroneDeployment } from './useDroneDeployment';

const DroneExperience = dynamic(
  () => import('./DroneExperience').then((module) => module.DroneExperience),
  { ssr: false },
);

export function DroneHero() {
  const scopeRef = useRef<HTMLDivElement>(null);
  const pinTargetRef = useRef<HTMLDivElement>(null);
  const progress = useMemo<DeploymentProgress>(() => ({ value: 0 }), []);
  const [sceneReady, setSceneReady] = useState(false);
  const [motionReduced, setMotionReduced] = useState<boolean | null>(null);
  const [stage, setStage] = useState<DroneStage>('dormant');
  const [activePart, setActivePart] = useState<DronePartId | null>(null);

  const handleStageChange = useCallback((nextStage: DroneStage) => setStage(nextStage), []);
  const timelineRef = useDroneDeployment({
    scope: scopeRef,
    pinTarget: pinTargetRef,
    progress,
    sceneReady: sceneReady && motionReduced === false,
    onStageChange: handleStageChange,
  });

  useEffect(() => {
    const preference = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setMotionReduced(preference.matches);
    update();
    preference.addEventListener('change', update);
    return () => preference.removeEventListener('change', update);
  }, []);

  const handleSceneReady = useCallback(() => {
    setSceneReady(true);
    requestAnimationFrame(() => ScrollTrigger.refresh());
  }, []);

  const toggleSystem = () => {
    const target = isOperationalStage(stage) ? 0.04 : 0.92;
    if (timelineRef.current) {
      gsap.to(timelineRef.current, { progress: target, duration: 0.8, ease: 'power2.inOut', overwrite: true });
      return;
    }
    gsap.to(progress, {
      value: target,
      duration: 0.8,
      ease: 'power2.inOut',
      overwrite: true,
      onUpdate: () => {
        const nextStage = getDroneStage(progress.value);
        setStage((current) => current === nextStage ? current : nextStage);
      },
    });
  };

  const status = motionReduced || stage === 'activate'
    ? 'SYSTEM READY'
    : stage === 'dormant'
      ? 'SYSTEM INIT'
      : 'SYSTEM ' + stage.toUpperCase();

  return (
    <div ref={scopeRef} className="drone-scene">
      <div className="drone-scene__head">
        <span>Deployment / 01</span>
        <span aria-live="polite">{status}</span>
      </div>
      <div ref={pinTargetRef} className="drone-scene__story">
        <div className="drone-scene__art">
          {motionReduced === null || motionReduced ? (
            <DroneSvgFallback state="activate" activePart={activePart} />
          ) : (
            <DroneExperience
              progress={progress}
              activePart={activePart}
              onSelect={setActivePart}
              onReady={handleSceneReady}
              fallback={<DroneSvgFallback state="activate" activePart={activePart} />}
            />
          )}
        </div>
      </div>
      <div className="drone-scene__controls">
        <button type="button" className="system-toggle" onClick={toggleSystem} aria-pressed={isOperationalStage(stage)}>
          <span className="system-toggle__dot" aria-hidden="true" />
          {isOperationalStage(stage) ? 'Reassemble the system' : 'Open the system'}
        </button>
        <p>Scroll to deploy the system. Use the component index to inspect the role of each subsystem.</p>
      </div>
      <DroneAnnotations activePart={activePart} onSelect={setActivePart} />
      <p className="drone-scene__text-equivalent">
        This visual maps distributed intelligence into an engineered autonomous system: an airframe, rotor assembly, embedded electronics, flight controller, sensor integration, payload management and autonomous navigation.
      </p>
    </div>
  );
}
